command -v python3>/dev/null||exit 127;python3 -u -c 'import sys,os,json as j,subprocess as p;A=sys.argv[1:];T=A[0]if A else"Philosophy";F=A[1]if len(A)>1 else"course.md";N=int(A[2])if len(A)>2 else 12;Q=os.getenv("AI","");X=lambda s:(lambda r:r.stdout.strip()if not r.returncode else"")(p.run(Q,shell=True,input=s,text=True,capture_output=True))if Q else"";f=os.getenv("SOURCE_PACK","sources/bibliography.txt");S=[x.strip()for x in open(f)if x.strip()and x[0]!="#"]if os.path.isfile(f)else[];ref="\n".join("[SRC:%d] %s"%(i+1,x)for i,x in enumerate(S))if S else"[SOURCE NEEDED]";O="\n".join("- Objective %d: define, explain, apply, analyze, or evaluate."%i for i in range(1,6));D=lambda i:(lambda h:(lambda m:"### Learning Objectives\n"+O+"\n### Chapter Overview\nStudy "+h+".\n### Key Terms\n"+T+", concept, argument, evidence.\n### Main Text\n"+m+"\n### Learning Activity\nState a claim, objection, and reply.\n### Self-Assessment\nExplain concepts and evaluate an argument.\n### Answer Key\nDefine terms, state premises, test objections, distinguish evidence.\n### Chapter Summary\nReview objectives and questions.\n### References\n"+ref)(X("Write a rigorous university lesson on "+h+". Give arguments, evidence, objections and replies; invent no citations.")or"Offline framework: define terms, reconstruct arguments, test objections, distinguish evidence, and mark claims for verification."))(T+" Unit "+str(i+1));R=[D(i)for i in range(N)];L=[T+" Unit "+str(i+1)for i in range(N)];Z=["# "+T,"","## Course Profile","","Independent-study course; verify factual claims.","","## Contents"]+["%d. %s"%(i+1,h)for i,h in enumerate(L)]+sum((["","## Chapter %d - %s"%(i+1,L[i]),"",R[i]]for i in range(N)),[])+["","## Course Review","","Review objectives, arguments, weak areas, and sources."];Z="\n".join(Z);q=F+".tmp";open(q,"w").write(Z);os.replace(q,F);print(j.dumps({"R":0,"MODE":"ai"if Q else"fallback","SOURCES":bool(S)},separators=(",",":")))' "$@"
